#!/usr/bin/env python3
# reserve_L53a.py — 새 과 L53a(바닷속 버터 부교 ① 부표 사람과 구슬 기둥) · 새 세계 s53
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
T = '[2026-11-13 새 과 L53a]'
new = {
 '바닷속을 가로지른 노란 버터 띠 + 머리만 물에 내놓은 두 줄 부표 사람': f'세포막(인지질 이중층) · 인지질(양친매성) 전용 {T} — 새 세계 「바닷속 버터 부교」(s53 · L53a ~ c). 부표 사람 = 줄무늬 둥근 머리(친수성 머리 · 물에) + 긴 두 다리(소수성 꼬리 둘 · 버터 속에) · 윗줄 빨간 머리 = 바깥 층 · 아랫줄 파란 머리 = 안쪽 층(비대칭) · 띠 위 밝은 물 = 세포 밖 · 아래 짙은 물 = 세포 안. 다리가 곧음 = 포화 · 무릎이 꺾임 = 불포화 · 다리가 짧음 = 짧은 꼬리 · 머리 곁 떨림 선 = 측면확산. 버터는 【녹아 흐르는 버터 / 얼어 고드름 달린 버터】(L50b 막 유동성)를 띠로 키운 것 — 왼쪽 끝은 얼고(고드름 · 얼음 속 일꾼 = 굳으면 효소 불활성) 오른쪽 끝은 햇살에 녹는다(기우는 작은 기둥 = 너무 묽으면 단백질을 못 받침). ⚠ 머리는 늘 띠 밖 · 다리는 늘 띠 속(바탕 두 장이 머리를 버터 속에 그려 버렸다 — 배치 밑그림을 주고 다시 그렸다). ⚠ 야영장의 호숫가 천 울타리(L48d · L48e = 세포막을 벽으로 본 것)와 세계로 가른다 — 막의 속을 들여다볼 때는 이 버터 띠.',
 '버터 띠를 꿰뚫은 알록달록 구슬 기둥 / 파란 머리에 사슬로 매달린 작은 구슬 공': f'내재단백질(막관통) / 주변부단백질 전용 {T} — L53a s8 · s9. 구슬 = 아미노산 · 구슬 사슬 = 단백질(【구슬 — 빛깔과 놓인 곳으로 가름】) 그대로 — 띠에 박히면 막단백질. 맨 왼쪽 기둥은 띠 속에서만 사슬이 꼬불꼬불 감겼고(소수성 α나선) 꼭대기에 맨 흰 알(α). 기둥마다 달린 물건이 기능이다(수활전인결부): 가운데 뚫린 굴(수송) · 아래 끝 작업대의 일꾼(효소 활성) · 빨간 우편함 + 켜진 등(신호전달 — 【붉은 물길에 떠가는 흰 봉투 + 꼴 맞는 우편함 집】과 같은 봉투 · 우편함) · 막대사탕 다발(세포-세포 인식) · 큰 회색 대갈못으로 이웃 부교의 기둥과 이어짐(세포 간 결합 — L14a 대갈못 = 데스모솜) · 위 밧줄 그물(ECM) + 아래 살구색 구슬 줄(미세섬유)에 묶임(부착). L53b · c 의 통로 · 운반체 · 펌프도 이 기둥으로 그린다.',
 '주황 오리발을 신고 띠 속에 선 잠수부 + 아래로 굽은 검은 화살': f'플립페이스(flippase — 특정 인지질을 한쪽 층으로 옮김 · 플립플롭은 드묾) 전용 {T} — L53a s3. 오리발(flipper) = 플립. 든 부표 사람의 머리가 파랑(아랫줄 빛) = 제 줄로 돌려놓음 → 두 층의 비대칭.',
 '부표 사람 줄에 낀 소 머리(유난히 긴 곧은 다리) · 돼지 머리(곧은 다리)': f'소기름 = 스테아르산(C18) · 돼지기름 = 팔미트산(C16) 전용 {T} — L53a s5(다리 길이 = 탄소 수 · 둘 다 곧은 다리 = 포화 · 언 쪽에 섬). ⚠ L31d 의 온몸 분홍 돼지(열쇠를 걸거나 앞발로 미는 일꾼) = PG(인산글리세르산 · 피그)와 가른다 — 이쪽은 머리만 있고 부표 사람처럼 다리 둘.',
 '다리 사이에 낀 금빛 타일(고리 넷 문장)': f'막 속 콜레스테롤(인지질 사이에 낌 · 온도 완충) 전용 {T} — L53a s6. 꺾인 다리 쪽의 타일 = 체온에서 옆걸음을 막음(유동성 ↓) · 언 곳 타일의 노란 둘레 = 굳지 못하게 함(고체화 방지). 문장은 【금빛 고리 넷 덩이】(스테로이드 골격) — PIL(L53a_pil1.py)로 그렸다.',
 '위쪽 이웃 부교에서 내려와 막대사탕을 양옆에서 집는 하늘색 Y 집게': f'세포-세포 인식(이웃 세포의 단백질이 당 표지를 알아봄) · 면역글로불린 당단백질 전용 {T} — L53a s11. Y 집게 = 【하늘색 Y자 집게】(면역글로불린 · L46c). PIL 로 그렸다.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('녹아 흐르는 버터 / 얼어 고드름 달린 버터', f'★ {T} L53a 가 이 버터를 바닷속을 가로지르는 띠(세포막)로 키웠다 — 왼쪽 끝은 얼어 고드름 · 오른쪽 끝은 햇살에 녹아 흐름.')
add('막대사탕', f'★ {T} L53a s11 · s13 구슬 기둥 꼭대기의 분홍 막대사탕 다발 = 당단백질(식별 표지) · 윗줄 빨간 부표 머리에 꽂힌 막대사탕 = 당지질 · 아랫줄 파란 머리엔 없음(당은 세포 바깥 면에만).')
add('금빛 고리 넷 덩이(육각 셋 + 오각 하나가 붙은 한 덩이)', f'★ {T} L53a s6 부표 사람 다리 사이 금빛 타일의 문장 = 막 속 콜레스테롤(세로로 세워 그림 · PIL).')
add('하늘색 Y자 집게', f'★ {T} L53a s11 이웃 부교에서 내려와 막대사탕을 집는 Y 집게 = 면역글로불린(당단백질 · 세포-세포 인식).')
add('알 · 감 · 베 (α · γ · β)', f'★ {T} L53a s9 맨 왼쪽 구슬 기둥 꼭대기의 맨 흰 알 = α나선의 α.')
add('구슬 — 빛깔과 놓인 곳으로 가름', f'★ {T} L53a 버터 띠를 꿰뚫은 알록달록 구슬 기둥 = 막단백질 · 둘째 기둥의 굴을 지나는 작은 구슬 = 작은 분자 · 이온(L14a#3 맨 관 속 작은 구슬과 같은 뜻) · 아래로 뻗은 살구색 구슬 줄 = 미세섬유(L14b).')
add('붉은 물길에 떠가는 흰 봉투 + 꼴 맞는 우편함 집', f'★ {T} L53a s10 구슬 기둥 꼭대기의 빨간 우편함에 꽂힌 흰 봉투 + 기둥 아래 끝의 켜진 노란 등 = 막단백질의 신호전달(수용체).')
add('노란 꼬불꼬불 꼰 줄 / 팽팽한 살구색 줄', f'★ {T} L53a s12 구슬 기둥 아래 끝에 이어진 살구색 구슬 줄 = 미세섬유(세포골격 부착).')
add('삼밧줄 / 금빛 밧줄', f'★ {T} L53a s12 구슬 기둥 위 끝을 묶은 물 위의 밧줄 그물 = 세포외기질(ECM — 자리로 가른다: 세포 밖 물에 뜬 그물).')
add('동전 투입구 크랭크 펌프', f'★ {T} 버터 부교 세계(L53c)에서도 Na⁺-K⁺ 펌프는 이 동전 크랭크 펌프로 그린다(계획 G1).')
open(P, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=1))
print('예약', len(R))
